INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué cláusula de COBOL cierra un archivo 38?', 'STOP', 'END', 'EXIT', 'CLOSE', 'D', 'Junior', 'CLOSE termina el procesamiento del archivo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué bloque inicia y termina un programa ejecutable en Informix 4GL?', 'El bloque MAIN ... END MAIN.', 'El bloque START ... END START.', 'La función program_entry().', 'El procedimiento PROCEDURE main().', 'A', 'Junior', 'MAIN inicia la ejecución del programa y END MAIN la termina.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué palabra de 4GL declara variables locales y registros?', 'DECLARE', 'DEFINE', 'VAR', 'DIM', 'B', 'Junior', 'DEFINE declara variables, arreglos y registros en el programa.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se declara un registro con todas las columnas de una tabla?', 'DECLARE reg_cliente TYPE cliente.ALL', 'DEFINE reg_cliente STRUCT OF cliente', 'DEFINE reg_cliente RECORD LIKE cliente.*', 'DIM reg_cliente AS TABLE cliente', 'C', 'Junior', 'RECORD LIKE tabla.* hereda las columnas y sus tipos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia selecciona la base de datos activa en Informix 4GL?', 'USE nombre_base_datos.', 'CONNECT TO DATABASE nombre_base_datos', 'OPEN DATABASE nombre_base_datos.', 'DATABASE nombre_base_datos.', 'D', 'Junior', 'DATABASE nombre_db selecciona la base de datos activa', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué variable indica el resultado de la última operación en 4GL?', 'status (y la estructura sqlca.sqlcode)', 'return_code', 'error_num', 'sys_status', 'A', 'Junior', 'status refleja el resultado de la última operación SQL o de pantalla.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué significa status = 0 después de una sentencia SQL?', 'No se encontró ningún registro que cumpliera con el criterio de búsqueda', 'La operación SQL se completó exitosamente sin incidencias.', 'La tabla está bloqueada por otro usuario de la red.', 'Se produjo una violación de clave primaria duplicada', 'B', 'Junior', 'El valor 0 indica que la operación terminó correctamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué indica status = 100 (NOTFOUND) en un SELECT o FETCH?', 'Que el usuario no posee permisos de lectura sobre la tabla consultada.', 'Que la base de datos se quedó sin espacio físico de almacenamiento.', 'Que no existen más registros o no se encontró ninguno que cumpla las condiciones.', 'Que se ha superado el número máximo de conexiones simultáneas.', 'C', 'Junior', '100 indica que no se encontró una fila o que terminó el conjunto.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia crea una ventana con posición y dimensiones en 4GL?', 'INIT DIALOG nombre ON SCREEN(linea, columna), en transacciones distribuidas.', 'CREATE DISPLAY WINDOW nombre AT x, y, optimizando el rendimiento de las operaciones.', 'SHOW SCREEN nombre WITH POSITION(x, y), garantizando la integridad referencial.', 'OPEN WINDOW nombre AT linea, columna WITH filas ROWS, columnas COLUMNS.', 'D', 'Junior', 'OPEN WINDOW crea una ventana con posición y dimensiones definidas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencias cargan y muestran un formulario compilado?', 'OPEN FORM nombre FROM \"archivo\" y DISPLAY FORM nombre.', 'LOAD SCREEN FROM \"archivo\" y SHOW FORM nombre.', 'IMPORT WINDOW \"archivo\" AS nombre.', 'ATTACH FORM \"archivo\" TO WINDOW nombre.', 'A', 'Junior', 'OPEN FORM carga el formulario; DISPLAY FORM lo muestra.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia captura datos del formulario en variables homónimas?', 'READ INTO lista_variables', 'INPUT BY NAME lista_variables', 'CAPTURE FROM SCREEN INTO lista_variables', 'GET FIELDS lista_variables', 'B', 'Junior', 'INPUT BY NAME enlaza campos del formulario con variables homónimas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia crea un menú interactivo en Informix 4GL?', 'SELECT MENU ... CASE ... END SELECT', 'CHOICE LIST ... OPTION ... END CHOICE', 'MENU \"titulo\" ... COMMAND \"opcion\" ... END MENU', 'BAR MENU ... BUTTON ... END BAR', 'C', 'Junior', 'MENU define opciones interactivas que el usuario puede seleccionar.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué extensión tienen los fuentes de Informix 4GL?', 'sql', 'cbl', 'prg', '4gl', 'D', 'Junior', 'Los fuentes de Informix 4GL usan la extensión .4gl.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué extensión tienen los archivos fuente de formularios 4GL?', '.per (que se compilan en archivos ejecutables .frm con formcompiler).', '.scr (que se compilan en binarios .bin)', '.ui (que se compilan en archivos .xml)', '.fmt (que se compilan en archivos .txt', 'A', 'Junior', 'Los diseños de formularios usan .per y se compilan a .frm.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué directiva permite continuar tras un error SQL en 4GL?', 'ON ERROR RESUME NEXT', 'WHENEVER ERROR CONTINUE', 'IGNORE SQL ERRORS TRUE', 'TRY CATCH ALL', 'B', 'Junior', 'WHENEVER ERROR CONTINUE permite gestionar errores sin abortar.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia muestra variables en campos homónimos del formulario?', 'WRITE FIELDS lista_variables', 'PRINT TO FORM lista_variables', 'DISPLAY BY NAME lista_variables', 'RENDER INTO lista_variables', 'C', 'Junior', 'DISPLAY BY NAME muestra variables en campos del mismo nombre.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se define una función con parámetros en Informix 4GL?', 'PROCEDURE nombre(p1, p2) ... GOBACK r1 ... END PROCEDURE', 'SUB nombre(p1, p2) ... RETURNING r1 ... END SUB', 'DEF nombre(p1, p2) ... OUTPUT r1 ... END DEF', 'FUNCTION nombre(p1, p2) ... RETURN r1 ... END FUNCTION', 'D', 'Junior', 'FUNCTION define la función; RETURN devuelve valores y END FUNCTION la cierra.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué tipo de dato genera un entero secuencial automáticamente?', 'SERIAL', 'AUTOINCREMENT', 'IDENTITY', 'SEQUENCE', 'A', 'Junior', 'SERIAL genera automáticamente un entero secuencial.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia inicia una transacción en Informix?', 'START TRANSACTION', 'BEGIN WORK', 'INIT TRANS', 'OPEN WORK', 'B', 'Junior', 'BEGIN WORK inicia la transacción; COMMIT confirma y ROLLBACK revierte.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia confirma los cambios de una transacción?', 'SAVE TRANSACTION', 'APPLY WORK', 'COMMIT WORK', 'CONFIRM WORK', 'C', 'Junior', 'COMMIT WORK confirma y hace permanentes los cambios.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia revierte los cambios de una transacción?', 'CANCEL WORK', 'ABORT WORK', 'UNDO TRANSACTION', 'ROLLBACK WORK', 'D', 'Junior', 'ROLLBACK WORK cancela la transacción y revierte sus cambios.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia crea criterios de búsqueda desde un formulario?', 'CONSTRUCT BY NAME cláusula_where ON lista_columnas', 'BUILD QUERY INTO cláusula_where FROM lista_columnas.', 'CREATE FILTER cláusula_where ON lista_columnas', 'SEARCH CRITERIA INTO cláusula_where FOR lista_columnas', 'A', 'Junior', 'CONSTRUCT arma criterios WHERE a partir de datos ingresados', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia solicita un dato simple mediante un mensaje?', 'ASK \"Mensaje\" INTO variable', 'PROMPT \"Mensaje\" FOR variable', 'READLINE \"Mensaje\" TO variable', 'INPUTLINE \"Mensaje\" AS variable', 'B', 'Junior', 'PROMPT muestra el mensaje y captura la entrada en una variable.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué operador compara cadenas con patrones y comodines?', 'El operador CONTAINS', 'El operador REGEXP', 'El operador MATCHES', 'El operador SIMILAR', 'C', 'Junior', 'MATCHES compara patrones; * coincide con varios caracteres y ? con uno', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia borra los valores de un formulario activo?', 'BLANK ALL', 'ERASE SCREEN', 'RESET DISPLAY', 'CLEAR FORM (o CLEAR WINDOW nombre)', 'D', 'Junior', 'CLEAR FORM limpia los valores visibles del formulario activo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué tipo almacena fecha y hora con precisión en Informix?', 'DATETIME YEAR TO SECOND', 'TIMESTAMP ISO', 'DATETIME64', 'TIME_RECORD', 'A', 'Junior', 'DATETIME almacena fecha y hora con la precisión especificada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué bloque se ejecuta antes de iniciar la entrada del usuario?', 'ON START', 'BEFORE INPUT', 'INIT INPUT', 'PRE INPUT', 'B', 'Junior', 'BEFORE INPUT se ejecuta antes de que comience la captura.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué evento valida un campo cuando el usuario sale de él?', 'POST FIELD nombre_campo', 'ON EXIT FIELD nombre_campo', 'AFTER FIELD nombre_campo', 'VALIDATE FIELD nombre_campo', 'C', 'Junior', 'AFTER FIELD se activa al salir del campo y permite validarlo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia mueve el foco a otro campo del formulario?', 'SET FIELD nombre_campo', 'GOTO FIELD nombre_campo', 'FOCUS nombre_campo', 'NEXT FIELD nombre_campo', 'D', 'Junior', 'NEXT FIELD dirige el foco al campo indicado.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia cierra una ventana de Informix 4GL?', 'CLOSE WINDOW nombre_ventana', 'DESTROY WINDOW nombre_ventana', 'EXIT WINDOW nombre_ventana', 'HIDE WINDOW nombre_ventana', 'A', 'Junior', 'CLOSE WINDOW cierra la ventana y muestra la ventana subyacente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué palabra permite heredar el tipo de una columna en DEFINE?', 'TYPE (ejemplo: DEFINE mi_var TYPE cliente.nombre)', 'LIKE (ejemplo: DEFINE mi_var LIKE cliente.nombre', 'AS (ejemplo: DEFINE mi_var AS cliente.nombre)', 'COPY (ejemplo: DEFINE mi_var COPY cliente.nombre)', 'B', 'Junior', 'LIKE tabla.columna hereda el tipo y la longitud de esa columna.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué variable indica una interrupción del teclado en 4GL?', 'cancel_status', 'break_key', 'int_flag', 'sys_abort', 'C', 'Semi-Senior', 'int_flag indica una interrupción capturada, como Control-C', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia permite gestionar Control-C sin abortar el programa?', 'TRAP CONTROL_C', 'BLOCK INTERRUPT', 'IGNORE BREAK', 'DEFER INTERRUPT', 'D', 'Junior', 'DEFER INTERRUPT permite manejar la interrupción mediante código.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia muestra un error y emite un sonido?', 'ERROR \"Mensaje de fallo\"', 'ALERT \"Mensaje de fallo\"', 'BELL \"Mensaje de fallo\"', 'PRINT_ERR \"Mensaje de fallo\"', 'A', 'Junior', 'ERROR muestra el mensaje de error y emite un pitido.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia muestra mensajes informativos sin sonido?', 'INFO \"Operación completada\"', 'MESSAGE \"Operación completada\"', 'NOTIFY \"Operación completada\"', 'NOTE \"Operación completada\"', 'B', 'Junior', 'MESSAGE muestra texto informativo sin señal audible.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cuál es el ciclo habitual para usar y liberar un cursor?', 'CREATE cursor, LOAD cursor, GET cursor INTO variables y UNLOAD cursor', 'INIT cursor, START cursor, READ variables, STOP cursor y DROP cursor', 'DECLARE cursor CURSOR FOR SELECT; OPEN, FETCH INTO variables y CLOSE cursor', 'ALLOCATE cursor, EXECUTE cursor, NEXT INTO variables y DEALLOCATE cursor', 'C', 'Semi-Senior', 'El ciclo típico es DECLARE, OPEN, FETCH, CLOSE y FREE', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué simplifica FOREACH al recorrer un cursor?', 'Calcula el número total de filas de una tabla sin necesidad de abrir transacciones', 'Recorre un array estático en memoria sin consultar la base de datos', 'Ejecuta múltiples sentencias INSERT en paralelo aprovechando hilos de hardware', 'Abre el cursor, recorre sus filas con FETCH y lo cierra al terminar.', 'D', 'Semi-Senior', 'FOREACH recorre filas del cursor y simplifica su manejo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué cláusula permite actualizar la fila actual de un cursor?', 'DECLARE c CURSOR FOR SELECT columna FROM tabla FOR UPDATE', 'DECLARE c CURSOR FOR SELECT columna FROM tabla WITH LOCK ROW', 'DECLARE c CURSOR FOR SELECT columna FROM tabla ALLOW MODIFY', 'DECLARE c CURSOR FOR SELECT columna FROM tabla AS EDITABLE', 'A', 'Semi-Senior', 'FOR UPDATE habilita UPDATE WHERE CURRENT OF para ese cursor.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué cursor permite optimizar inserciones masivas en Informix?', 'Deshabilita índices antes de cada inserción para acelerar la carga.', 'Usa un cursor INSERT que acumula filas en un búfer antes de escribirlas', 'Activa una directiva de compilación que convierte INSERT en llamadas directas.', 'Inserta registros solo cuando la base de datos está fuera de línea.', 'B', 'Semi-Senior', 'Un cursor INSERT con PUT y FLUSH agrupa inserciones para acelerar cargas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué aislamiento permite leer cambios aún no confirmados?', 'SET ISOLATION TO CURSOR STABILITY', 'SET ISOLATION TO COMMITTED READ', 'SET ISOLATION TO DIRTY READ', 'SET ISOLATION TO REPEATABLE READ', 'C', 'Semi-Senior', 'DIRTY READ permite leer datos aún no confirmados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué aislamiento permite leer solo datos confirmados?', 'SET ISOLATION TO OPEN ACCESS', 'SET ISOLATION TO DIRTY READ', 'SET ISOLATION TO UNCOMMITTED READ', 'SET ISOLATION TO COMMITTED READ', 'D', 'Semi-Senior', 'COMMITTED READ solo permite leer datos confirmados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia permite esperar por registros bloqueados?', 'SET LOCK MODE TO WAIT [segundos]', 'SET TIMEOUT TO WAIT', 'SET CONCURRENCY RETRY [segundos]', 'SET BLOCKING PAUSE [segundos]', 'A', 'Senior', 'SET LOCK MODE TO WAIT espera a que se libere el bloqueo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué error Informix indica que un registro está bloqueado?', '-206', '-107 (o -154 / -244 según el contexto de aislamiento)', '-239', '-310', 'B', 'Semi-Senior', 'El error -107 indica que otro proceso mantiene bloqueado el registro.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué error SQL indica una clave única o primaria duplicada?', '-107', '-206', '-239 (ISAM error -100)', '-556', 'C', 'Semi-Senior', 'El error -239 señala una clave UNIQUE o PRIMARY KEY duplicada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia prepara una cadena SQL para ejecución dinámica?', 'TRANSLATE SQL cadena_sql AS nombre_stmt', 'COMPILE SQL cadena_sql INTO nombre_stmt', 'BUILD STMT nombre_stmt USING cadena_sql', 'PREPARE nombre_stmt FROM cadena_sql', 'D', 'Semi-Senior', 'PREPARE analiza y prepara la sentencia SQL dinámica.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia ejecuta SQL preparado con parámetros?', 'EXECUTE nombre_stmt USING var1, var2', 'RUN nombre_stmt WITH var1, var2', 'CALL nombre_stmt PARAMS var1, var2', 'DO nombre_stmt ARGS var1, var2', 'A', 'Semi-Senior', 'EXECUTE ... USING pasa valores a los marcadores y ejecuta el SQL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué bloques estructuran el formato de un reporte 4GL?', 'Usa DOCUMENT, SECTIONS y END DOCUMENT para estructurar el documento', 'Usa REPORT, OUTPUT, FORMAT y END REPORT para definir el reporte', 'Usa PRINT LAYOUT, PAGES y END LAYOUT para definir la impresión.', 'Usa TEMPLATE, BODY y END TEMPLATE para definir una plantilla.', 'B', 'Semi-Senior', 'REPORT usa bloques FORMAT como HEADER, EVERY ROW y TRAILER.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencias inician, alimentan y finalizan un reporte?', 'OPEN REPORT nombre, WRITE REPORT nombre(datos) y STOP REPORT nombre', 'INIT REPORT nombre, SEND TO REPORT nombre(datos) y CLOSE REPORT nombre', 'START REPORT nombre, OUTPUT TO REPORT nombre(datos) y FINISH REPORT nombre', 'BEGIN REPORT nombre, PUSH REPORT nombre(datos) y COMMIT REPORT nombre', 'C', 'Semi-Senior', 'START REPORT inicia, OUTPUT TO REPORT envía filas y FINISH REPORT termina.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué bloque ejecuta acciones cuando cambia un grupo de reporte?', 'END GROUP OF nombre_columna', 'ON BREAK OF nombre_columna', 'POST GROUP nombre_columna', 'AFTER GROUP OF nombre_columna', 'D', 'Semi-Senior', 'AFTER GROUP OF ejecuta acciones al cambiar el valor de agrupación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué función suma automáticamente valores de un grupo en REPORT?', 'GROUP SUM(columna)', 'TOTAL(columna)', 'ACCUM(columna)', 'AGGREGATE_SUM(columna)', 'A', 'Semi-Senior', 'GROUP SUM(campo) acumula los valores del grupo automáticamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sección del reporte se ejecuta por cada registro?', 'FOR EACH RECORD', 'ON EVERY ROW', 'ON DATA LINE', 'PER ROW ACTION', 'B', 'Semi-Senior', 'ON EVERY ROW procesa el formato de cada registro del reporte.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se envía la salida de un reporte a un archivo?', 'REDIRECT OUTPUT \"ruta_archivo.txt\"', 'SET PRINTER TO FILE \"ruta_archivo.txt\"', 'START REPORT nombre TO archivo; también puede definirse OUTPUT en REPORT', 'EXPORT REPORT TO \"ruta_archivo.txt\"', 'C', 'Semi-Senior', 'START REPORT ... TO dirige la salida del reporte a un archivo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué diferencia hay entre bloqueo ROW y PAGE en Informix?', 'Son idénticos en concurrencia y solo varían en la sintaxis de creación de índices', 'ROW exige desactivar el logging y PAGE requiere almacenamiento especial.', 'PAGE permite solo lectura; ROW se limita a cargas masivas de datos.', 'ROW bloquea solo la fila modificada y permite mayor concurrencia.', 'D', 'Semi-Senior', 'ROW bloquea filas; PAGE bloquea páginas y puede afectar más registros.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se recorre desde 4GL un procedimiento SPL que devuelve filas?', 'Declara un cursor para ejecutar el procedimiento y leer sus filas.', 'Invocando directamente RUN PROCEDURE nombre_proc(parámetros)', 'Llamando a la función interna call_spl(nombre_proc)', 'No es posible consultar procedimientos almacenados desde Informix 4GL', 'A', 'Semi-Senior', 'Un cursor con EXECUTE PROCEDURE recorre filas devueltas por SPL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué cláusula SPL devuelve una fila y continúa la ejecución?', 'YIELD valor', 'RETURN valor WITH RESUME', 'OUTPUT ROW valor', 'EMIT valor CONTINUOUS', 'B', 'Semi-Senior', 'RETURN ... WITH RESUME devuelve una fila y permite continuar luego.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve la variable de entorno INFORMIXSERVER?', 'Establece la ruta del directorio temporal donde se compilan los archivos .per', 'Define el nombre del archivo de licencia criptográfica del sistema operativo', 'Indica el nombre de la instancia de Informix a la que se conectará el cliente', 'Indica el número máximo de procesadores asignados a la máquina virtual', 'C', 'Semi-Senior', 'INFORMIXSERVER identifica la instancia Informix a la que se conecta el cliente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué archivo relaciona la instancia Informix con host y servicio?', '/var/log/informix.cfg', '/etc/hosts.equiv', '$INFORMIXDIR/etc/onconfig', '$INFORMIXDIR/etc/sqlhosts', 'D', 'Semi-Senior', 'sqlhosts mapea servidor, protocolo, host y servicio de red.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué archivo contiene parámetros del motor, como BUFFERPOOL?', '$INFORMIXDIR/etc/onconfig (o $ONCONFIG)', '$INFORMIXDIR/etc/sqlhosts', '/etc/services', '$INFORMIXDIR/etc/registry', 'A', 'Semi-Senior', 'onconfig define parámetros de memoria, logs y comportamiento del motor.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué comando muestra estado, memoria e hilos de Informix?', 'dbaccess', 'onstat (ejemplo: onstat -u, onstat -l, onstat -g ses)', 'onspaces', 'onmode', 'B', 'Semi-Senior', 'onstat muestra diagnósticos de estado, memoria y actividad del servidor.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué herramienta de consola permite ejecutar sentencias SQL de consulta y administración en Informix', 'isql', 'sqlplus', 'dbaccess', 'pgadmin', 'C', 'Semi-Senior', 'dbaccess permite ejecutar SQL, consultar datos y administrar esquemas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve el comando administrativo onmode?', 'Monitorear la temperatura física de los procesadores del servidor', 'Crear copias de respaldo comprimidas de las tablas en cintas virtuales', 'Compilar formularios .per en código binario ejecutable', 'Cambia el modo del motor (Online, Quiescent o Shutdown) o fuerza una sesión.', 'D', 'Semi-Senior', 'onmode cambia el estado del servidor y gestiona sesiones.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué tabla de catálogo registra tablas y vistas de la base?', 'systables', 'information_schema.tables', 'sys_catalog_tables', 'all_tables', 'A', 'Semi-Senior', 'systables contiene metadatos de tablas, vistas y sinónimos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué tabla de catálogo describe las columnas de cada tabla?', 'sysfields', 'syscolumns', 'sysattributes', 'column_catalog.', 'B', 'Semi-Senior', 'syscolumns registra nombres, tipos y longitudes de las columnas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué sentencia importa variables globales compartidas en 4GL?', 'IMPORT GLOBALS FROM \"archivo_globales.4gl\"', 'INCLUDE \"archivo_globales.h\"', 'GLOBALS \"archivo_globales.4gl', 'SHARED VARIABLES \"archivo_globales.4gl\"', 'C', 'Semi-Senior', 'GLOBALS importa variables compartidas entre módulos 4GL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿En qué difieren EXIT PROGRAM e INTERRUPT en 4GL?', 'Son sinónimos y devuelven siempre el mismo código al sistema operativo', 'EXIT PROGRAM reinicia el servidor; INTERRUPT apaga la instancia.', 'INTERRUPT borra todos los archivos compilados del directorio de trabajo', 'EXIT PROGRAM termina el programa y cierra ordenadamente sus recursos', 'D', 'Semi-Senior', 'EXIT PROGRAM termina el programa; INTERRUPT activa la lógica de interrupción.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué cláusula captura teclas especiales durante INPUT o MENU?', 'ON KEY (F1, F2, CONTROL-W)', 'CATCH KEYBOARD (F1)', 'WHEN PRESSED (F1)', 'TRAP KEY (F1)', 'A', 'Semi-Senior', 'ON KEY define acciones para teclas especiales durante la entrada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué devuelve sqlca.sqlerrd[2] tras generar un valor SERIAL?', 'Almacena el número total de errores de hardware registrados en el disco duro', 'El último valor SERIAL asignado por el motor a la columna insertada.', 'Indica el tiempo en microsegundos que demoró la inserción en la base de datos.', 'Contiene el número de usuarios conectados a la misma tabla simultáneamente.', 'B', 'Semi-Senior', 'sqlca.sqlerrd[2] contiene el último valor SERIAL generado.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué indica sqlca.sqlerrd[3] tras una operación DML?', 'Almacena el código de retorno de la tarjeta de red del servidor', 'Indica el porcentaje de fragmentación de los índices de la tabla', 'Indica cuántas filas afectó la última operación INSERT, UPDATE o DELETE', 'Contiene el número de transacciones concurrentes en espera de confirmación', 'C', 'Semi-Senior', 'sqlca.sqlerrd[3] informa cuántas filas fueron procesadas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve sysmaster en la supervisión de Informix?', 'Es un catálogo consultable únicamente cuando la instancia está apagada.', 'Es una base de respaldo en frío que guarda copias de contraseñas y datos.', 'Un repositorio de archivos ejecutables donde residen los compiladores de Informix 4GL', 'Es una base de datos virtual que expone tablas y vistas de supervisión del motor.', 'D', 'Senior', 'Explicación: sysmaster expone información de sesiones, bloqueos y actividad del motor.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se identifican sesiones que mantienen bloqueos en sysmaster?', 'Cruza syslocks y syssessions para identificar la sesión (sid) que mantiene bloqueos.', 'Consultando la tabla systables en busca de columnas con valor lock_active = true', 'Ejecutando un SELECT sobre la tabla temporal syserrors en la base de datos de usuario', 'Busca los bloqueos leyendo archivos de log con grep en el sistema operativo.', 'A', 'Senior', 'Explicación: Relacionar syslocks con syssessions permite identificar sesiones bloqueadoras', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué ventaja ofrece LOCK MODE ROW frente a PAGE?', 'Duplica el espacio en disco de las páginas de datos de cada dbspace.', 'Reduce el bloqueo de filas vecinas ubicadas en la misma página de datos.', 'Impide crear índices compuestos con más de dos columnas en la tabla.', 'Deshabilita las transacciones atómicas y obliga a operar sin ellas.', 'B', 'Senior', 'ROW reduce conflictos entre usuarios que modifican filas distintas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué causa el error Lock table overflow en Informix?', 'Se supera el número máximo de usuarios registrados en el sistema operativo del servidor', 'El disco de la base de datos se llena; puede requerirse liberar o ampliar espacio.', 'Se agota el límite de bloqueos en memoria; puede ampliarse la configuración de locks.', 'El compilador detecta una variable con un nombre de más de 18 caracteres de longitud', 'C', 'Senior', 'Las operaciones agotan el límite de bloqueos configurado en LOCKS.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué directiva genera sqexplain.out con el plan SQL?', 'SHOW EXECUTION PATH', 'EXPLAIN QUERY PLAN', 'ENABLE SQL TRACE', 'SET EXPLAIN ON', 'D', 'Senior', 'SET EXPLAIN ON escribe el plan de ejecución en sqexplain.out.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Por qué ejecutar UPDATE STATISTICS periódicamente?', 'Actualiza estadísticas de distribución en sysdistrib para ayudar al optimizador.', 'Comprime las tablas en disco y reduce el tamaño de sus bloques de almacenamiento.', 'Elimina las copias de seguridad antiguas almacenadas en los dbspaces secundarios.', 'Borra automáticamente los usuarios que no han iniciado sesión en los últimos 30 días', 'A', 'Senior', 'Las estadísticas precisas ayudan al optimizador a elegir planes eficientes.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué ocurre al alcanzar el límite de una transacción larga?', 'Una consulta SELECT de más de diez minutos cancela automáticamente la conexión.', 'Al alcanzar el límite, Informix puede detener la transacción y revertirla.', 'Un script de 4GL que supera las 10,000 líneas de código fuente no puede ser compilado', 'Una tabla que tiene más de 50 índices definidos bloquea el inicio de la instancia', 'B', 'Senior', 'Una transacción sin COMMIT retiene Logical Logs y puede impedir que se reutilicen.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿En qué difiere un dbspace temporal de uno normal?', 'Los dbspaces temporales solo almacenan enteros y no admiten otros tipos de datos.', 'Los DBSPACETEMP se eliminan físicamente del disco cada 60 minutos.', 'DBSPACETEMP guarda tablas temporales y resultados intermedios de ordenamientos.', 'No hay diferencias técnicas; es solo otro nombre para un dbspace normal.', 'C', 'Senior', 'DBSPACETEMP aloja temporales y puede evitar generar logs para ellas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve oncheck en el mantenimiento de Informix?', 'Restaura contraseñas de usuarios en el directorio activo corporativo', 'Compila los programas fuente de 4GL en ejecutables binarios de alto rendimiento', 'Envía alertas por correo electrónico cuando la temperatura del servidor se incrementa', 'Verifica la estructura de páginas, índices y datos, y puede reparar inconsistencias.', 'D', 'Senior', 'oncheck verifica la integridad física de datos, índices y páginas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se crea un trigger para auditar cambios en una tabla?', 'CREATE TRIGGER audita UPDATE ON tabla FOR EACH ROW EXECUTE PROCEDURE auditar()', 'CREATE AUDIT RULE ON columna IN tabla DO LOG', 'ATTACH LISTENER TO columna ON tabla RUN PROCEDURE', 'SET WATCHPOINT ON columna FOR TABLE tabla ACTION', 'A', 'Senior', 'CREATE TRIGGER define eventos y acciones de auditoría por fila.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es lo correcto hablando de diferencias entre un índice B-Tree y uno CLUSTER?', 'Un índice CLUSTER solo puede ser creado en tablas temporales en memoria RAM', 'Un índice CLUSTER ordena físicamente las filas según el índice en las páginas de datos.', 'Un índice B-Tree estándar no permite búsquedas directas por clave de igualdad', 'Un índice CLUSTER triplica el tamaño de cada fila para guardar copias adicionales.', 'B', 'Senior', 'CLUSTER ordena físicamente las filas de la tabla según la clave del índice.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué garantiza el aislamiento REPEATABLE READ en Informix?', 'Fuerza a que las consultas SELECT se repitan automáticamente si ocurre un error de red', 'Permite leer cada registro solo dos veces dentro de una misma transacción.', 'Bloquea las filas seleccionadas e impide que otras sesiones las cambien', 'Desactiva bloqueos de actualización y permite modificar filas simultáneamente', 'C', 'Senior', 'REPEATABLE READ evita lecturas sucias y no repetibles durante la transacción.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirven ontape y onbar en Informix?', 'Generar estadísticas de uso de memoria para el sistema operativo Linux', 'Comprimir el código fuente de los archivos .4gl en formato comprimido', 'Monitorear el tráfico de paquetes TCP en los adaptadores de red', 'Administra respaldos en caliente de niveles 0, 1 y 2, y la restauración de datos', 'D', 'Senior', 'ontape y onbar realizan respaldos y protegen los logical logs.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué configuran INFORMIXCONTIME e INFORMIXCONRETRY?', 'Definen el tiempo de espera de conexión y cuántos reintentos se harán antes de fallar.', 'Controlan la velocidad de renderizado de los formularios en la pantalla del usuario', 'Definen el número máximo de líneas de un reporte antes de hacer un salto de página', 'Indican la cantidad de memoria asignada a variables globales de tipo entero', 'A', 'Senior', 'Configuran tiempos de espera y reintentos durante la conexión.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se fragmenta una tabla por una expresión en Informix?', 'Creando copias de la tabla y combinándolas mediante consultas para simular fragmentación.', 'Usa FRAGMENT BY EXPRESSION o FRAGMENT BY ROUND ROBIN al crear la tabla.', 'Dividiendo el archivo de código fuente de 4GL en múltiples módulos independientes', 'Configurando una red privada virtual exclusiva entre los discos duros', 'B', 'Senior', 'FRAGMENT BY EXPRESSION distribuye filas en fragmentos según condiciones.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la eliminación de fragmentos en una consulta?', 'El motor combina los fragmentos en una sola tabla durante la noche', 'Elimina los fragmentos que no se han consultado durante cierto tiempo.', 'Evalúa el WHERE y consulta solo los fragmentos que pueden contener filas coincidentes.', 'El optimizador convierte los fragmentos en índices en memoria RAM', 'C', 'Senior', 'El optimizador omite fragmentos que no cumplen la condición WHERE.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué indica el error SQL -206 en Informix?', 'El programa intenta abrir un archivo que ya fue cerrado previamente', 'El disco duro de almacenamiento temporal se encuentra lleno al 100%', 'Se ha superado el número de columnas permitidas en una sentencia SELECT', 'La tabla indicada no existe en la base de datos.', 'D', 'Senior', 'El error -206 suele indicar una tabla inexistente o mal calificada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve la utilidad onspaces?', 'Crea, modifica o elimina dbspaces y chunks para administrar el almacenamiento físico.', 'Configurar los privilegios de acceso de los usuarios en el sistema operativo', 'Analizar la ortografía de los comentarios en el código fuente de los programas', 'Compilar procedimientos almacenados en código ensamblador nativo', 'A', 'Senior', 'onspaces crea y administra dbspaces y sus chunks de almacenamiento.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué cláusula mantiene abierto un cursor tras COMMIT?', 'DECLARE c PERSISTENT CURSOR FOR SELECT columna FROM tabla', 'DECLARE c CURSOR WITH HOLD FOR SELECT columna FROM tabla.', 'DECLARE c CURSOR FOR SELECT columna FROM tabla KEEP OPEN.', 'DECLARE c CURSOR FOR SELECT columna FROM tabla NO COMMIT CLOSE.', 'B', 'Senior', 'WITH HOLD conserva el cursor abierto después de COMMIT WORK.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué efecto tiene CLEANERS en el archivo onconfig?', 'Define el número de días que se retienen los registros de auditoría en el sistema', 'Establece la frecuencia con la que se eliminan los archivos temporales de compilación', 'Define cuántos hilos limpiadores de páginas se ejecutarán en el servidor de la BD.', 'Controla el brillo y contraste de las ventanas en pantalla de los terminales', 'C', 'Senior', 'CLEANERS escriben páginas modificadas de memoria a disco.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es un checkpoint en Informix?', 'Una verificación de sintaxis que se ejecuta antes de cada sentencia INSERT', 'Un reinicio automático de la máquina virtual cada medianoche para refrescar recursos', 'Un escaneo de virus realizado sobre los archivos de código fuente compilados', 'Punto de sincronización que escribe páginas modificadas y registra el estado del motor.', 'D', 'Senior', 'El checkpoint sincroniza datos en memoria con el disco para recuperación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué significa el estado Quiescent en Informix?', 'El motor está en modo administrativo; solo informix o root puede conectarse.', 'La instancia está completamente apagada y no consume ningún recurso de memoria', 'El motor opera a máxima capacidad con miles de transacciones concurrentes.', 'La base de datos se encuentra en modo de solo lectura para todos los usuarios de la red', 'A', 'Senior', 'Quiescent restringe la instancia a tareas administrativas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué ventaja ofrece Forest of Trees en índices B-Tree?', 'Almacena los índices en forma de árboles binarios simples en archivos de texto plano', 'Divide un índice muy usado en varios árboles B-Tree independientes para repartir carga.', 'Desactiva los índices durante el día y los reconstruye automáticamente en la noche', 'Permite que los índices solo contengan caracteres alfabéticos en minúsculas', 'B', 'Senior', 'Forest of Trees reduce la contención al dividir el índice en subárboles.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se consulta una tabla en otra instancia Informix?', 'Descargando la base de datos completa por FTP antes de ejecutar la consulta', 'Creando un túnel SSH en cada consulta mediante la sentencia RUN SYSTEM', 'Usa base_datos@instancia_remota:tabla para consultar una tabla de otra instancia', 'No es posible consultar bases de datos remotas en motores Informix', 'C', 'Senior', 'La sintaxis db@server:owner.table permite consultas entre instancias.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve Enterprise Replication (ER/CDR)?', 'Un generador de certificados digitales para comunicaciones por correo electrónico', 'Un compilador que traduce código fuente de Informix 4GL a código fuente de C++', 'Una utilidad que duplica las pantallas de terminal para formación de nuevos usuarios', 'Replica datos de forma asíncrona mediante los registros del Logical Log.', 'D', 'Senior', 'ER/CDR replica cambios entre servidores y puede resolver conflictos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué administra la utilidad onparams en Informix?', 'Efectúa la administración de los logical logs y el physical log.', 'Modificar las contraseñas de los usuarios en la base de datos de auditoría', 'Ajustar la velocidad de los ventiladores de la caja del servidor', 'Configurar los tipos de fuentes tipográficas admitidos en las pantallas .per', 'A', 'Senior', 'onparams añade, elimina o redimensiona Logical Logs y cambia su ubicación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo reducir bloqueos en reportes pesados de producción?', 'Detener el motor de base de datos durante la ejecución del reporte', 'Usa DIRTY READ o consulta una réplica secundaria de solo lectura para reducir bloqueos.', 'Convertir todos los datos numéricos de la tabla a formato de texto alfanumérico', 'Borrar los índices de la tabla antes de iniciar la consulta de extracción', 'B', 'Senior', 'DIRTY READ reduce bloqueos; también pueden usarse réplicas para reportes', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es un par HDR en Informix?', 'Una tarjeta madre con dos procesadores centrales de diferente fabricante', 'Dos terminales de pantalla conectadas al mismo teclado para trabajo colaborativo', 'Dos servidores Primary y Secondary sincronizan datos de forma casi simultánea.', 'Es un sistema de archivos que respalda programas 4GL en cintas.', 'C', 'Senior', 'HDR mantiene un secundario sincronizado para alta disponibilidad.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿En qué difieren BLOBspace y Smart Large Objects?', 'Son idénticos en almacenamiento y solo varían en el nombre del comando de creación', 'Los SBSPACES solo admiten archivos de audio y los BLOBspaces solo admiten texto plano', 'Los Smart Large Objects no pueden ser consultados mediante lenguaje SQL', 'BLOBspaces almacenan BYTE/TEXT; SBSPACES almacenan Smart Large Objects.', 'D', 'Senior', 'SBSPACE almacena BLOB/CLOB con acceso parcial y soporte transaccional.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué ventaja ofrece el plan compilado de una rutina SPL?', 'El motor guarda el plan de ejecución en memoria compartida para reutilizarlo.', 'Anota la función con la directiva STATIC_EXECUTION_ONLY en la cabecera', 'Convierte el procedimiento en una macro de ensamblador en el sistema operativo', 'Elimina todos los parámetros de entrada de la firma de la función', 'A', 'Senior', 'El motor guarda planes compilados en sysprocplan para reutilizarlos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué configura DBMONEY en el cliente Informix?', 'Convierte automáticamente los valores monetarios a la tasa de cambio del día', 'Define cómo se muestran los valores MONEY, incluido el símbolo monetario.', 'Bloquea las transacciones que superen un millón de unidades monetarias', 'Deshabilita las operaciones de suma y resta en campos de tipo financiero', 'B', 'Senior', 'DBMONEY define el símbolo monetario y los separadores decimales y de miles.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirven dbexport y dbimport en Informix?', 'dbimport traduce automáticamente consultas de SQL a código de lenguaje C', 'dbexport envía los datos por correo electrónico comprimidos en formato RAR', 'dbexport genera el esquema SQL y exporta los datos; dbimport los vuelve a cargar.', 'Son herramientas que solo funcionan con bases de datos que no superen los 10 megabytes', 'C', 'Senior', 'dbexport extrae esquema y datos; dbimport los carga en otra base.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué controla PSORT_NPROCS en ordenamientos de Informix?', 'PSORT_NPROCS divide los registros en bloques fijos de exactamente 128 bytes', 'PSORT_NPROCS desactiva la ordenación del motor y obliga al cliente a ordenar los datos.', 'PSORT_NPROCS limita el número de usuarios que consultan a la vez.', 'PSORT_NPROCS define cuántos subprocesos paralelos se usan para ordenar datos.', 'D', 'Senior', 'PSORT_NPROCS ajusta el paralelismo usado en operaciones de ordenamiento.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es la computación en la nube (Cloud Computing)?', 'La entrega de servicios de cómputo (servidores, storage, DB) por internet.', 'Un tipo de hardware instalado en oficinas para procesar datos localmente.', 'Un protocolo de comunicación para transferir datos entre dispositivos.', 'Una red privada que conecta múltiples centros de datos corporativos.', 'A', 'Junior', 'Cloud Computing ofrece recursos bajo demanda (IaaS, PaaS, SaaS) con pago por uso.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es Kubernetes en el contexto de aplicaciones IA en la nube?', 'Un framework de ML para entrenar modelos en múltiples GPUs en paralelo.', 'Un orquestador de contenedores para desplegar y escalar aplicaciones.', 'Una plataforma de monitoreo de modelos de IA en tiempo real.', 'Un sistema de bases de datos distribuidas para almacenar embeddings.', 'B', 'Junior', 'Kubernetes gestiona pods de contenedores, auto-scaling y load balancing para APIs de IA.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el alucinamiento (hallucination) en LLMs?', 'Cuando el modelo rechaza responder por restricciones de seguridad.', 'Cuando el modelo genera respuestas repetidas sin variación creativa.', 'Cuando el modelo genera información falsa o inventada como si fuera verdadera.', 'Cuando el modelo olvida el contexto previo de la conversación actual.', 'C', 'Junior', 'Las alucinaciones ocurren porque los LLMs predicen tokens plausibles, no verifican hechos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué hace la técnica Few-Shot Prompting?', 'Selecciona pocos tokens relevantes del contexto para responder.', 'Entrena el modelo con pocos ejemplos de forma rápida y eficiente.', 'Reduce la cantidad de tokens del prompt para ahorrar costos de API.', 'Incluye algunos ejemplos de entradas y salidas en el prompt para guiar al modelo.', 'D', 'Junior', 'Few-shot: prompt=\"Traducir inglés→español. apple→manzana. car→coche. house→?\"', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es MLflow en el contexto de MLOps?', 'Una plataforma open-source para rastrear experimentos y versionar modelos ML.', 'Un framework de ML de Google para entrenar redes neuronales en la nube.', 'Un orquestador de pipelines de datos para preparar datasets de entrenamiento.', 'Una herramienta de visualización de métricas de modelos en producción.', 'A', 'Junior', 'MLflow registra parámetros, métricas y artefactos por experimento para reproducibilidad.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el Chain-of-Thought (CoT) prompting?', 'Encadenar múltiples LLMs donde la salida de uno es la entrada del siguiente.', 'Técnica que pide al modelo razonar paso a paso antes de dar la respuesta.', 'Una cadena de prompts almacenados en base de datos para reutilización.', 'Técnica para reducir tokens concatenando prompts relacionados entre sí.', 'B', 'Semi-Senior', '\"Piensa paso a paso\" mejora la precisión en tareas de razonamiento matemático y lógico.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el Model Context Protocol (MCP) de Anthropic?', 'Un sistema de caché para reutilizar el KV cache entre diferentes llamadas.', 'Un protocolo para gestionar el contexto de múltiples sesiones del mismo LLM.', 'Un protocolo estándar para conectar LLMs con herramientas y fuentes de datos.', 'Un protocolo de seguridad para validar los prompts antes de procesarlos.', 'C', 'Semi-Senior', 'MCP estandariza cómo los LLMs acceden a tools, recursos y prompts de sistemas externos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el RLHF (Reinforcement Learning from Human Feedback)?', 'Un sistema de aprendizaje activo donde el modelo pregunta al usuario.', 'Un método para entrenar robots físicos usando retroalimentación de humanos.', 'Un proceso de validación donde humanos revisan los datasets de entrenamiento.', 'Técnica para alinear LLMs usando evaluaciones humanas como señal de recompensa.', 'D', 'Semi-Senior', 'RLHF: supervisado → reward model con preferencias humanas → RL (PPO) para alinear el LLM.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué hace el prompt system message en APIs de LLMs como OpenAI?', 'Define el rol, restricciones y comportamiento base del asistente de IA.', 'Configura los parámetros técnicos como temperatura y max tokens de la API.', 'Inicializa el historial de conversación con mensajes previos del usuario.', 'Define las funciones (tools) que el modelo puede invocar durante la sesión.', 'A', 'Semi-Senior', 'System message: \"Eres un asistente experto en COBOL que responde en español conciso.\"', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es la perplexity y cómo se usa para evaluar LLMs?', 'El número de respuestas únicas que el modelo genera para el mismo prompt.', 'El exponente de la entropía cruzada; menor valor indica mejor modelado del lenguaje.', 'La varianza de las respuestas del modelo medida en múltiples ejecuciones.', 'El número de tokens de contexto que el modelo puede recordar correctamente.', 'B', 'Senior', 'Perplexity = e^(H); mide cuán sorprendido está el modelo ante el corpus de evaluación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué modelo se usa en IA generativa 1?', 'RNN', 'CNN', 'LLM', 'SVM', 'C', 'Junior', 'LLM es la base de IA generativa moderna.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué modelo se usa en IA generativa 2?', 'SVM', 'CNN', 'RNN', 'LLM', 'D', 'Junior', 'LLM es la base de IA generativa moderna.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué modelo se usa en IA generativa 3?', 'LLM', 'CNN', 'RNN', 'SVM', 'A', 'Junior', 'LLM es la base de IA generativa moderna.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué modelo se usa en IA generativa 4?', 'CNN', 'LLM', 'RNN', 'SVM', 'B', 'Junior', 'LLM es la base de IA generativa moderna.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué modelo se usa en IA generativa 5?', 'RNN', 'CNN', 'LLM', 'SVM', 'C', 'Junior', 'LLM es la base de IA generativa moderna.', 1);
